const n="// 传统沙箱脚本 - 使用 registerFunction 注册函数\r\n// 上下文变量：$api, $route, $data, $el, $query, $queryAll, $rebindRules, $refreshData, $dataSet, $call 都已注入\r\n\r\n// 页面初始化\r\nconsole.log('🚀 工作台页面已加载 (传统沙箱执行)');\r\nconsole.log('📦 页面数据:', $data);\r\nconsole.log('🛣️ 当前路由:', $route?.path);\r\nconsole.log('📄 页面容器:', $el);\r\nconsole.log('🔥 这是一个明显的测试日志，应该在控制台中看到');\r\n\r\n// 注册页面函数\r\nregisterFunction('testButtonClick', function() {\r\n    alert('✅ JavaScript 执行成功！\\n按钮变色说明 CSS 也生效了！');\r\n    console.log('🎯 测试按钮被点击');\r\n\r\n    // 访问表单 API\r\n    if ($api) {\r\n        console.log('📋 表单值:', $api.formData());\r\n    }\r\n\r\n    // 访问 DOM 元素\r\n    if ($el) {\r\n        console.log('📄 页面容器元素:', $el);\r\n        console.log('📏 容器高度:', $el.offsetHeight);\r\n    }\r\n\r\n    // 查询页面中的按钮\r\n    const buttons = $queryAll('button');\r\n    console.log('🔘 页面中有', buttons?.length, '个按钮');\r\n});\r\n\r\nregisterFunction('showAlert', function() {\r\n    const now = new Date().toLocaleTimeString();\r\n    alert('🔔 当前时间: ' + now);\r\n});\r\n\r\nregisterFunction('getFormData', function() {\r\n    if ($api) {\r\n        const data = $api.formData();\r\n        console.log('📋 表单数据:', data);\r\n        alert('表单数据: ' + JSON.stringify(data, null, 2));\r\n        return data;\r\n    }\r\n    console.warn('⚠️ 表单 API 未就绪');\r\n    return null;\r\n});\r\n\r\nregisterFunction('handleInputChange', function(value) {\r\n    console.log('📝 输入值变化:', value);\r\n    if ($api) {\r\n        console.log('当前表单数据:', $api.formData());\r\n    }\r\n});\r\n\r\nregisterFunction('handleRowClick', function(row, column, event) {\r\n    console.log('📊 点击行:', row);\r\n    console.log('📊 点击列:', column);\r\n    alert('点击了行: ' + JSON.stringify(row));\r\n});\r\n\r\n// 示例：操作 DOM 元素\r\nregisterFunction('highlightButtons', function() {\r\n    const buttons = $queryAll('button');\r\n    if (buttons) {\r\n        buttons.forEach((btn, index) => {\r\n            setTimeout(() => {\r\n                btn.style.transform = 'scale(1.1)';\r\n                setTimeout(() => {\r\n                    btn.style.transform = 'scale(1)';\r\n                }, 200);\r\n            }, index * 100);\r\n        });\r\n    }\r\n    console.log('✨ 按钮高亮动画执行');\r\n});\r\n\r\n// 私有辅助函数（在沙箱作用域内）\r\nfunction formatDate(date) {\r\n    return date.toLocaleDateString('zh-CN');\r\n}\r\n\r\n// 配置对象（在沙箱作用域内）\r\nconst config = {\r\n    pageName: '工作台',\r\n    version: '1.0.0',\r\n    initTime: new Date().toISOString()\r\n};\r\n\r\nconsole.log('⚙️ 页面配置:', config);\r\n\r\n";export{n as default};
